import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.OED5XGjC.js";const u=JSON.parse('{"title":"Release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function c(d,e,n,l,i,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="release-model" tabindex="-1">Release model <a class="header-anchor" href="#release-model" aria-label="Permalink to &quot;Release model&quot;">​</a></h1><p>Releases are repo automation, not manual steps: <code>scripts/release.sh</code> is triggered by bupha watch on each <code>main</code> push — a debounce window (default 5 min, <code>MYCO_RELEASE_DEBOUNCE</code>) means only the last push in a quiet window actually releases. The script runs inside a detached worktree and pushes commits and tags from there, never from the main checkout.</p><h2 id="what-a-release-run-does" tabindex="-1">What a release run does <a class="header-anchor" href="#what-a-release-run-does" aria-label="Permalink to &quot;What a release run does&quot;">​</a></h2><ol><li><strong>Diff since the last tag</strong> — crates under <code>crates/</code> that changed since <code>git describe --tags</code> are the release set; the <code>myco</code> binary re-publishes whenever any crate changed. No crate changes, no release.</li><li><strong>Per-crate patch bump + publish</strong> — <code>cargo set-version -p &lt;crate&gt; --bump patch</code>, then <code>cargo publish</code> with retries. Each crate gets its own tag <code>&lt;crate&gt;-v&lt;ver&gt;</code> — versions diverge independently in the monorepo.</li><li><strong>Commit + push</strong> — one <code>release: bump crate versions</code> commit, pushed to <code>main</code> with the tags.</li><li><strong>Binary dist</strong> — when <code>dist</code> and <code>gh</code> are available, a local <code>dist build</code> produces the shell installer (<code>dist-workspace.toml</code>, host arch <code>x86_64-unknown-linux-gnu</code> only — other targets are a TODO for remote workers), uploaded to a GitHub Release <code>myco-v&lt;ver&gt;</code> with generated notes.</li></ol><p>With no tags at all the script exits early — the flow is seeded by tagging once.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>The crates.io name <code>myco</code> is currently held by an unrelated project, so <code>cargo publish</code> of the CLI package depends on resolving that; installs should use <code>cargo install --git https://github.com/9aia/myco</code> regardless.</li><li>Library crates publish normally under their <code>myco-*</code> names.</li></ul><h2 id="ci-and-docs-deploys" tabindex="-1">CI and docs deploys <a class="header-anchor" href="#ci-and-docs-deploys" aria-label="Permalink to &quot;CI and docs deploys&quot;">​</a></h2><p>The same bupha watch owns the rest of what used to be GitHub Actions — there are no workflows in the repo:</p><ul><li><strong>Push to <code>docs</code></strong> runs <code>scripts/deploy-docs.sh</code>, which rebuilds the site and pushes <code>gh-pages</code> — Pages is a legacy branch deploy, so that push is the whole release of the site.</li><li><strong>Push to <code>main</code></strong> is gated locally by the <code>pre-push</code> hook (<code>cargo xtask check</code>). <code>scripts/ci.sh</code> (<code>check &amp;&amp; test</code>) is ready for bupha, but the watcher routes one <code>branch</code> per repo name today — a second <code>9aia/myco</code> entry needs bupha&#39;s <code>[[repo.jobs]]</code> work (its T-004).</li></ul>',10)])])}const m=o(r,[["render",c]]);export{u as __pageData,m as default};
